"""Golden dataset types. Human-verified ground truth; never generated by an LLM.

A dataset version is a folder ``<datasets_dir>/<version>/`` holding ``dataset.yaml``
(manifest) and ``cases.yaml`` (list of cases). Versions are immutable once used by a
baseline: the content hash detects silent edits.
"""

import hashlib
import json
import re
from datetime import date
from enum import StrEnum
from typing import Any

from pydantic import Field, field_validator

from regguard.core.types import FrozenModel

_TAG_PATTERN = r"^[a-z][a-z0-9_]*$"


class Difficulty(StrEnum):
    EASY = "easy"
    MEDIUM = "medium"
    HARD = "hard"


class GoldenCase(FrozenModel):
    # Named GoldenCase (not TestCase) so pytest never tries to collect it.
    id: str = Field(pattern=r"^[a-z0-9][a-z0-9_-]*$", max_length=64)
    input: dict[str, str]
    expected: dict[str, Any]
    difficulty: Difficulty
    tags: tuple[str, ...] = ()
    critical: bool = False
    notes: str = ""

    @field_validator("tags")
    @classmethod
    def _check_tags(cls, tags: tuple[str, ...]) -> tuple[str, ...]:
        bad = [t for t in tags if not re.match(_TAG_PATTERN, t)]
        if bad:
            raise ValueError(f"tags must be lowercase snake_case: {bad}")
        if len(set(tags)) != len(tags):
            raise ValueError("duplicate tags")
        return tags


class DatasetManifest(FrozenModel):
    name: str = Field(min_length=1)
    version: str = Field(pattern=r"^[A-Za-z0-9][A-Za-z0-9._-]*$")
    description: str = ""
    created_at: date | None = None
    changelog: tuple[str, ...] = ()


class Dataset(FrozenModel):
    manifest: DatasetManifest
    cases: tuple[GoldenCase, ...]

    @property
    def content_hash(self) -> str:
        """SHA-256 over everything that affects evaluation (notes excluded), order-independent."""
        cases = sorted(
            (c.model_dump(mode="json", exclude={"notes"}) for c in self.cases),
            key=lambda c: str(c["id"]),
        )
        canonical = json.dumps(cases, sort_keys=True, separators=(",", ":"), ensure_ascii=False)
        return "sha256:" + hashlib.sha256(canonical.encode("utf-8")).hexdigest()

    def get(self, case_id: str) -> GoldenCase:
        for case in self.cases:
            if case.id == case_id:
                return case
        raise KeyError(case_id)
